"""Measured explanations for chapter XII review questions 8–13 on printed page 291."""
import argparse
import json
from math import cos, radians, sin, sqrt
from coordinate_curves import graph
from triangle_relations import triangle_points
from triangle_sine_area import area, triangle
from trigonometry_review import review_entry
from vector_scaling import BOOK, ROOT

OUT=ROOT/'geometry-course/textbook/data/triangle-review.json'


def question(n,title,task,answer,hint,steps,views,checks,refs,caption):
    c=area(n,None,[291],task,answer,hint,steps,views,checks,refs=refs)
    c['visualization']['caption']=caption;c['visualization']['model']['description']=caption
    return review_entry(c,n,title)


def laws():
    views=[triangle('Положительная проекция при 30°','ABC',8,6,30),triangle('Проекция вне основания при 150°','ABC',8,6,150),triangle('Новая высота при прямом угле','ABC',5,4,90)]
    e=question(8,'Выведи площадь из двух сторон и угла','Сформулируй и докажи формулу площади треугольника через две стороны и угол между ними. Объясни, что меняется на рисунке при тупом угле.',
        'Пусть AB=c, AC=b, ∠A=α. Опусти высоту CH на прямую AB. Её длина b sin α, в том числе при тупом α, поскольку sin(180°−α)=sin α. Поэтому S=ch/2=bc sin α/2. При α=90° высота совпадает с AC.',
        'В качестве высоты бери перпендикуляр к прямой основания. Если H находится вне отрезка, высота остаётся положительной.',[
        ('Вырази высоту','Для c=8,b=6,α=30° высота CH=6·1/2=3. Поэтому S=8·3/2=12.','Формула с синусом использует угол между двумя заданными сторонами.'),
        ('Перенеси основание высоты за точку A','При α=150° точка H левее A. В прямоугольном ACH угол при A внутри малого треугольника равен 30°, а sin 150°=sin 30°. Высота и площадь остались равны 3 и 12.','Не подставляй cos α вместо положительной высоты.'),
        ('Проверь прямую конфигурацию','При c=5,b=4,α=90° получаем CH=4 и S=10. Во всех случаях формула получается из половины произведения основания на высоту.','Площадь выражается в квадратных единицах.')],views,[
        ('Чему равна площадь при c=8,b=6,α=150°?','12','Найди высоту 3 и умножь на половину основания.'),('Чему равна площадь новой прямоугольной фигуры?','10','Половина произведения катетов 5 и 4.')],[104],'H — основание перпендикуляра из C к прямой AB. При тупом угле он попадает за A.')
    tri={'A':(0,0),'B':(4,0),'C':(0,3)}
    views=[triangle_points('Катеты 3 и 4, гипотенуза 5',tri),
           triangle_points('Описанная окружность, центр K',dict(tri,K=(2,1.5)),circle=('K',2.5)),
           triangle_points('Подобный треугольник и окружность вдвое больше',{'A':(0,0),'B':(8,0),'C':(0,6),'K':(4,3)},circle=('K',5))]
    f=question(9,'Докажи теорему синусов','Сформулируй и докажи теорему синусов. Объясни, какую сторону надо сопоставить с каждым углом и каково общее отношение через радиус окружности.',
        'Если a,b,c лежат напротив A,B,C, то a/sin A=b/sin B=c/sin C. Действительно, 2S=bc sin A=ca sin B=ab sin C. Деление на abc даёт обратные отношения sin A/a, sin B/b и sin C/c. Общее отношение сторон к синусам равно диаметру 2R описанной окружности.',
        'Каждый синус должен стоять под противоположной стороной. Поскольку стороны и синусы внутренних углов положительны, обратные отношения существуют.',[
        ('Сравни три записи площади','В одном и том же треугольнике 2S=bc sin A=ca sin B=ab sin C. Деление каждой части на abc даёт требуемые пропорции. В прямоугольном образце a=BC=5, sin A=1.','Три площади не относятся к разным треугольникам.'),
        ('Свяжи отношение с диаметром','Проведи диаметр описанной окружности через конец хорды a. В полученном прямоугольном треугольнике синус вписанного угла, опирающегося на a, равен a/(2R). При дополнительном угле синус равен прежнему. Если сама a — диаметр, напротив лежит прямой угол.','Общее отношение равно удвоенному радиусу.'),
        ('Измени масштаб','При удвоении всех сторон углы прежние. Гипотенуза из 5 стала 10, радиус из 2,5 стал 5, общее отношение равно 10.','У подобных треугольников синусы соответствующих углов одинаковые, диаметры масштабируются.')],views,[
        ('Чему равно исходное a/sin A в образце с гипотенузой 5?','5','Углу A=90° противоположна BC.'),('Каково общее отношение в новом удвоенном треугольнике?','10','Чему равен диаметр окружности радиуса 5?')],[104,105],'A — вершина прямого угла в числовом примере, K — центр окружности с диаметром BC.')
    views=[triangle('Угол при A равен 60°','ABC',5,3,60),triangle('Угол заменён на 120°','ABC',5,3,120),triangle('Предельный переход к теореме Пифагора','ABC',5,3,90)]
    g=question(10,'Докажи теорему косинусов','Сформулируй и докажи выражение для квадрата стороны через две другие стороны и угол между ними.',
        'При a=BC,b=AC,c=AB верно a²=b²+c²−2bc cos A. Помести A в (0;0), B в (c;0), C в (b cos A;b sin A). Из формулы расстояния BC²=(b cos A−c)²+(b sin A)². После раскрытия и применения sin²A+cos²A=1 получается теорема.',
        'Квадрат разности содержит смешанный член со знаком минус. Для тупого угла сам косинус отрицательный, и искомая сторона увеличивается.',[
        ('Расположи точки','Когда b=3,c=5 и A=60°, координаты C=(3/2;3√3/2). Из формулы получаем a²=9+25−15=19.','Сторона a должна лежать напротив того угла, который стоит под косинусом.'),
        ('Проверь тупой угол в том же доказательстве','Для A=120° координаты C меняют знак абсциссы. Теперь a²=9+25+15=49. Алгебраическое раскрытие расстояния не требует положительного cos A.','При переходе через 90° меняется знак косинуса.'),
        ('Сделай угол прямым','У cos 90° значение 0 и смешанный член исчезает. При сторонах 3 и 5 новая гипотенуза имеет квадрат 34.','Теорема Пифагора — случай теоремы косинусов при прямом угле.')],views,[
        ('Каков квадрат стороны напротив 120° для b=3,c=5?','49','Вычти отрицательный смешанный член.'),('Чему равен квадрат BC при тех же сторонах и A=90°?','34','Сложи 3² и 5².')],[100,101,106],'Угол A лежит между AB и AC. Положение H отмечает проекцию вершины C на прямую AB.')
    return [e,f,g]


def construct():
    views=[triangle_points('Три стороны 3, 4, 5',{'A':(0,0),'B':(4,0),'C':(0,3)}),triangle('Две стороны 3 и 4, угол 60° между ними','ABC',4,3,60,False),
           triangle('Углы 30°, 60° у катета AB=6','ABC',6,3*sqrt(3),30,False)]
    return question(11,'Разбери три способа решить треугольник','Что означает решить треугольник? Приведи три основные постановки и укажи порядок нахождения неизвестных элементов.',
        'Решить треугольник — найти неизвестные стороны и углы по известным. По трём сторонам используем теорему косинусов для углов. По двум сторонам и углу между ними сначала находим третью сторону по косинусам. По стороне и двум прилежащим углам находим третий угол из суммы 180°, а остальные стороны по теореме синусов.',
        'Перед выбором формулы отметь данные на рисунке. При двух сторонах и угле проверь, лежит ли данный угол между этими сторонами.',[
        ('Даны три стороны','При AB=4, AC=3, BC=5 равенство 4²+3²=5² даёт A=90°. Получить тот же угол можно из cos A=(16+9−25)/(2·4·3)=0. Остальные углы однозначно определяются теоремой косинусов.','Сначала проверь неравенства треугольника.'),
        ('Две стороны и угол между ними','При b=3,c=4,A=60° найдём a²=9+16−12=13. Остальные углы можно вычислить по косинусам и сверить их сумму.','Из cos A=1/2 следует смешанный член 2·3·4·1/2=12.'),
        ('Сторона и два прилежащих угла','Пусть AB=6, A=30°, B=60°. Тогда C=90°. По синусам BC=6 sin 30°=3, AC=6 sin 60°=3√3. Получены все шесть элементов.','Число 6 относится к стороне напротив прямого угла.')],views,[
        ('Каков квадрат третьей стороны при b=3,c=4,A=60°?','13','Используй теорему косинусов.'),('Какова BC при AB=6,A=30°,B=60°?','3','Гипотенуза вдвое длиннее катета напротив 30°.')],[105,106,107],'Три рисунка представляют разные исходные данные. Сопоставь каждую известную сторону с её противоположным углом.')


def height_view(label,d1,d2,h):
    pts={'H':(0,0),'T':(0,h),'N':(d1,0),'F':(d2,0)}
    return graph(label,pts,edges=[('H','T'),('H','N'),('N','F'),('N','T'),('F','T')])


def measure_height():
    views=[height_view('Два пункта наблюдения перед предметом',4,10,6),height_view('Наблюдатели дальше, высота прежняя',6,12,6),height_view('Удвой все расстояния первого опыта',8,20,12)]
    return question(12,'Измерь высоту при недоступном основании','Как определить высоту предмета, если к его основанию нельзя подойти? Опиши, какие расстояния и углы нужно измерить на одном уровне.',
        'Выбери ближнюю N и дальнюю F в одной горизонтальной плоскости на одной прямой с проекцией вершины H, по одну сторону от H. Измерь NF=d и углы возвышения α из N, β из F. При α>β положим HN=x. Тогда h=x tg α=(x+d) tg β, откуда h=d·tg α·tg β/(tg α−tg β). Если инструмент выше основания на известную величину, учти эту поправку.',
        'Расстояние до недоступного основания неизвестно. Для двух наблюдений запиши одну и ту же высоту; расстояния различаются на измеренный базис.',[
        ('Запиши уравнения для двух наблюдателей','При NF=6, tg α=3/2, tg β=3/5 получаем h=3x/2=3(x+6)/5. Отсюда x=4 и h=6. Отрезок HN в настоящем измерении не нужно проходить.','Большему углу соответствует ближняя точка.'),
        ('Проверь сдвиг пунктов при прежней башне','Пусть HN=6, HF=12. Тогда tg α=1, tg β=1/2 и d=6. Формула даёт h=6·1·(1/2)/(1−1/2)=6.','Углы нужно снимать по одному горизонтальному уровню.'),
        ('Измени масштаб измерения','Если d=12 при прежних tg α=3/2 и tg β=3/5, похожие треугольники увеличились вдвое. Высота равна 12.','С теми же углами расстояния пропорциональны длине базиса.')],views,[
        ('Чему равна высота при d=6, tg α=1, tg β=1/2?','6','Подставь оба значения в выражение для h.'),('Какова высота при удвоенном исходном базисе d=12 и прежних исходных углах?','12','Используй пропорциональность базису.')],[100,105,108],'TH — высота от уровня наблюдений до вершины. N ближе к предмету, F дальше. Из измеряемых длин нужен отрезок NF.')


def target_view(label,base,alpha,beta):
    side=base*sin(radians(beta))/sin(radians(alpha+beta))
    return triangle_points(label,{'A':(0,0),'B':(base,0),'C':(side*cos(radians(alpha)),side*sin(radians(alpha)))})


def measure_distance():
    views=[target_view('Базис 10, оба угла по 60°',10,60,60),target_view('Новый угол при A равен 30°',10,30,60),target_view('Прямоугольный случай с базисом 12',12,60,30)]
    return question(13,'Измерь расстояние до недоступной точки','Как найти расстояние от A до видимой, но недоступной точки C? Из приборов доступны угломер и способ измерить базис AB.',
        'Выбери удобную B, отличную от A и не лежащую с A,C на одной прямой. Измерь AB=d, угол BAC=α и угол ABC=β. Тогда угол C=180°−α−β и AC=d·sin β/sin C. Обе визирные линии должны смотреть на одну и ту же точку C.',
        'Искомая AC расположена напротив угла при B. Измеряемый базис AB расположен напротив угла при C.',[
        ('Определи третий угол','В первом опыте AB=10, α=β=60°. Получаем C=60°, треугольник равносторонний, AC=10.','Для ненулевого треугольника сумма двух измеренных углов меньше 180°.'),
        ('Примени теорему синусов','При α=30°, β=60°, AB=10 имеем C=90°. Значит AC=10 sin 60°=5√3. Это наклонное расстояние до самой точки C.','Сторона BC лежит напротив α и при этих числах имеет другую длину.'),
        ('Проведи измерение с новым базисом','Теперь AB=12, α=60°, β=30°. Снова C=90°, но AC=12 sin 30°=6. При обращении порядка углов поменялись противоположные им стороны.','Сохраняй названия концов базиса от начала до конца вычисления.')],views,[
        ('Чему равен угол C при углах у базиса 30° и 60°?','90','Вычти сумму известных углов из 180°.'),('В третьем опыте какой длины AC при AB=12 и β=30°?','6','Подставь sin 30°=1/2 и sin C=1.')],[105,108],'AB — измеренный доступный базис. Визирные лучи из A и B пересекаются в недоступной точке C.')


def build():
    return {'bookId':BOOK,'lessons':laws()+[construct(),measure_height(),measure_distance()]}


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    output=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==output
    else:OUT.write_text(output)
